//! Where the money is earned, and what that place requires of you.
//!
//! Every number in this module is DATA with an effective date and a source, never a constant. That is
//! not tidiness: Georgia's flat income tax steps down on a published schedule, a county's sales tax
//! changes when a referendum passes, and a rate hard-coded in 2026 is a confident wrong number on a
//! 2027 tax return. So a rate that no longer covers the date being asked about is REFUSED, and the
//! refusal names the source to go read.
//!
//! # What this is not
//!
//! It is not tax advice and it does not file anything. It holds what a place requires, what it
//! charges, and where each figure came from, so a person or an accountant can check it. Nothing here
//! has been verified against its source by a human — [`sources`] exists to make that one pass.
//!
//! # Sales tax and VAT are different mechanisms
//!
//! A VAT country is modelled as far as knowing it IS one, and no further. Place-of-supply rules and
//! the reverse charge decide who accounts for the tax on a cross-border service, and neither is
//! implemented here — so asking for a sales-tax-shaped total in a VAT jurisdiction is refused rather
//! than answered with a number that would be wrong in a way nobody would notice until an audit.
use crate::money::{money, Money};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Country,
    /// A state, province or equivalent.
    Region,
    County,
    /// A city, town or village.
    Locality,
}

impl Level {
    pub fn label(self) -> &'static str {
        match self {
            Level::Country => "country",
            Level::Region => "region",
            Level::County => "county",
            Level::Locality => "locality",
        }
    }
}

/// How a place taxes consumption. The two are not variants of one thing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaxSystem {
    /// Charged once, at the final sale, by the seller. What the United States does.
    SalesTax,
    /// Charged at every stage with credit for inputs, and the CROSS-BORDER rules are the hard part.
    ValueAdded,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Place {
    /// A path, so the hierarchy is visible in the name: `us/ga/gwinnett/duluth`.
    pub id: &'static str,
    pub level: Level,
    pub name: &'static str,
    pub parent: Option<&'static str>,
    /// Set on a COUNTRY and inherited. A locality does not have its own currency or tax system.
    pub currency: Option<&'static str>,
    pub system: Option<TaxSystem>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RateKind {
    SalesTax,
    IncomeTax,
    /// Social Security + Medicare, paid on both halves when nobody else employs you.
    SelfEmployment,
    /// A locality's own levy on business gross receipts.
    OccupationalTax,
}

impl RateKind {
    pub fn label(self) -> &'static str {
        match self {
            RateKind::SalesTax => "sales tax",
            RateKind::IncomeTax => "income tax",
            RateKind::SelfEmployment => "self-employment tax",
            RateKind::OccupationalTax => "occupational tax",
        }
    }
    /// Whether the rates up a chain ADD. Sales tax does — state plus county plus city is one printed
    /// percentage. Income tax does not: federal and state are separate returns with separate bases,
    /// and summing them would invent a bracket that exists nowhere.
    pub fn stacks(self) -> bool {
        matches!(self, RateKind::SalesTax)
    }
}

/// A rate, in BASIS POINTS. Integer for the same reason money is: 5.19% is `519`, and no percentage
/// in this module is ever a float that can drift a hundredth of a point across an arithmetic chain.
#[derive(Debug, Clone, PartialEq)]
pub struct Rate {
    pub place: &'static str,
    pub kind: RateKind,
    pub bps: i64,
    pub from: &'static str,
    /// `None` means open-ended. A SCHEDULED change gets a real end date so the day it lapses the
    /// system refuses instead of quietly applying last year's number.
    pub to: Option<&'static str>,
    /// REQUIRED. A rate with no source is a rumour, and `every_seeded_rate_cites_a_source` refuses one.
    pub source: &'static str,
    pub note: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cadence {
    /// Done once, at the start.
    Once,
    /// Due on these (month, day) pairs every year.
    OnDates(&'static [(u32, u32)]),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Obligation {
    pub place: &'static str,
    pub name: &'static str,
    pub what: &'static str,
    /// Who you actually file with. A requirement whose authority is unnamed cannot be acted on.
    pub authority: &'static str,
    /// `None` when the fee is genuinely not a fixed number — a gross-receipts schedule, say. NOT the
    /// same as free, and the two must not render alike.
    pub cost_minor: Option<i64>,
    pub cadence: Cadence,
    /// THE CONDITION THAT TRIGGERS IT. Most of these are conditional, and telling somebody they need
    /// an LLC when a sole proprietorship is eligible is the expensive kind of wrong.
    pub required_when: &'static str,
    pub source: &'static str,
}

/// What is being sold. The distinction decides taxability and it is not cosmetic — Georgia does not
/// tax professional services but does tax specified digital products, so two invoices from the same
/// desk can differ.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Supply {
    ProfessionalService,
    TangibleGood,
    /// Downloaded software, e-books, media — a category several states changed recently.
    DigitalProduct,
    /// Access to hosted software. Distinct from a digital product: nothing is delivered.
    SoftwareAsService,
}

impl Supply {
    /// The short form a person types and a store holds.
    pub fn key(self) -> &'static str {
        match self {
            Supply::ProfessionalService => "service",
            Supply::TangibleGood => "good",
            Supply::DigitalProduct => "digital",
            Supply::SoftwareAsService => "saas",
        }
    }

    /// An unknown key is `None`, never a default — defaulting a supply would decide the taxability
    /// of an invoice on the strength of a typo.
    pub fn parse(s: &str) -> Option<Supply> {
        match s {
            "service" => Some(Supply::ProfessionalService),
            "good" => Some(Supply::TangibleGood),
            "digital" => Some(Supply::DigitalProduct),
            "saas" => Some(Supply::SoftwareAsService),
            _ => None,
        }
    }

    pub const ALL: &'static [Supply] = &[Supply::ProfessionalService, Supply::TangibleGood, Supply::DigitalProduct, Supply::SoftwareAsService];

    pub fn label(self) -> &'static str {
        match self {
            Supply::ProfessionalService => "professional service",
            Supply::TangibleGood => "tangible good",
            Supply::DigitalProduct => "digital product",
            Supply::SoftwareAsService => "software as a service",
        }
    }
}

/// Whether a place taxes a kind of supply, as DATA rather than a branch.
///
/// This started as an `if in_georgia` inside [`taxability`], which meant a second state could not be
/// added without editing code — the exact opposite of the point. A rule carries its own effective
/// date for the same reason a rate does: Georgia began taxing specified digital products on
/// 2024-01-01, and an invoice raised before that was correctly untaxed.
#[derive(Debug, Clone, PartialEq)]
pub struct SupplyRule {
    pub place: &'static str,
    pub supply: Supply,
    pub taxed: bool,
    /// Why, in the words you would want on the invoice when somebody asks.
    pub reason: &'static str,
    pub from: &'static str,
    pub to: Option<&'static str>,
    pub source: &'static str,
}

/// The answer to "do I charge tax on this", INCLUDING the answer "nobody here knows".
#[derive(Debug, Clone, PartialEq)]
pub enum Taxability {
    Taxable { bps: i64, sources: Vec<&'static str> },
    Exempt { reason: &'static str, source: &'static str },
    /// A first-class outcome. Charging nothing because the table was silent looks identical to
    /// charging nothing because the supply is exempt, and only one of those is defensible.
    Unknown { what_to_check: String, where_to_check: &'static str },
}

