/// Walk a place to its country, nearest first.
///
/// The cycle guard is not paranoia about the seed above — it is about the data a user adds. A parent
/// loop would hang the process, and a hang is the hardest failure to attribute.
/// Suggest the places closest to what was typed, rather than listing every id.
///
/// A refusal that prints all of them is a wall the reader skims past, and the one they wanted is in
/// it — which makes the refusal useless at exactly the moment it is being read.
fn nearest(places: &[Place], wanted: &str) -> String {
    let parent = wanted.rsplit_once('/').map(|(a, _)| a).unwrap_or("");
    let mut hits: Vec<&str> = places.iter().filter(|p| p.parent == Some(parent) || p.id.starts_with(wanted)).map(|p| p.id).collect();
    if hits.is_empty() {
        hits = places.iter().filter(|p| p.level <= Level::Region).map(|p| p.id).collect();
    }
    hits.truncate(8);
    if hits.is_empty() {
        String::new()
    } else {
        format!(" Did you mean: {}{}", hits.join(", "), if places.len() > hits.len() { " … (`bsc fin where places` for the rest)" } else { "" })
    }
}

pub fn chain(places: &[Place], id: &str) -> Result<Vec<Place>, String> {
    let mut out: Vec<Place> = Vec::new();
    let mut cursor = Some(id);
    while let Some(current) = cursor {
        let Some(p) = places.iter().find(|p| p.id == current) else {
            return Err(format!("`{current}` is not a place this knows.{}", nearest(places, current)));
        };
        if out.iter().any(|q| q.id == p.id) {
            return Err(format!("`{}` is its own ancestor — the parent chain loops, and following it would hang rather than answer", p.id));
        }
        out.push(p.clone());
        cursor = p.parent;
    }
    Ok(out)
}

/// The country a place sits in, and therefore its currency and tax system.
pub fn country(places: &[Place], id: &str) -> Result<Place, String> {
    let c = chain(places, id)?;
    c.into_iter()
        .find(|p| p.level == Level::Country)
        .ok_or_else(|| format!("`{id}` has no country above it — every place must reach one, because that is where the currency and the tax system are declared"))
}

/// Every rate of one kind that applies at a place on a date, nearest first.
///
/// A rate whose window has CLOSED is not returned, and that is the whole point of the window.
pub fn rates_at(rates: &[Rate], places: &[Place], id: &str, kind: RateKind, on: &str) -> Result<Vec<Rate>, String> {
    let c = chain(places, id)?;
    let mut out = Vec::new();
    for p in &c {
        for r in rates.iter().filter(|r| r.place == p.id && r.kind == kind) {
            if r.from <= on && r.to.is_none_or(|t| on <= t) {
                out.push(r.clone());
            }
        }
    }
    Ok(out)
}

/// The combined rate for a kind that STACKS, or a refusal naming what is missing.
///
/// The refusal is the valuable half. When Georgia's legislated step-down lapses, this stops answering
/// and says which place, which date and which source — rather than returning last year's percentage,
/// which is a number a person would put on a return without a second thought.
pub fn combined(rates: &[Rate], places: &[Place], id: &str, kind: RateKind, on: &str) -> Result<(i64, Vec<Rate>), String> {
    if !kind.stacks() {
        return Err(format!(
            "{} does not stack — federal and state are separate returns over separate bases, and adding them would invent a rate that exists nowhere. Ask for each level separately.",
            kind.label()
        ));
    }
    let found = rates_at(rates, places, id, kind, on)?;
    if found.is_empty() {
        let c = chain(places, id)?;
        let known: Vec<&str> = rates.iter().filter(|r| r.kind == kind && c.iter().any(|p| p.id == r.place)).map(|r| r.source).collect();
        return Err(format!(
            "no {} rate covers {on} for {id}. {}",
            kind.label(),
            if known.is_empty() {
                "Nothing is recorded at any level of this place.".to_string()
            } else {
                format!("Rates exist but their windows have closed — go to: {}", dedup(&known).join("; "))
            }
        ));
    }
    Ok((found.iter().map(|r| r.bps).sum(), found))
}

fn dedup(xs: &[&'static str]) -> Vec<&'static str> {
    let mut out: Vec<&'static str> = Vec::new();
    for x in xs {
        if !out.contains(x) {
            out.push(x);
        }
    }
    out
}

/// Whether a supply is taxed at a place, on a date.
///
/// Georgia is the seeded case and its answer is genuinely useful: professional services are not
/// taxable, which is why an IT consulting invoice from Duluth carries no sales tax at all.
/// Whether a supply is taxed at a place, on a date.
///
/// The nearest rule up the chain wins, so a city rule would override its state's. No rule at any
/// level is [`Taxability::Unknown`] — never a silent `false`, because charging nothing because the
/// table was empty is indistinguishable from charging nothing because the supply is exempt, and only
/// one of those survives being asked about.
pub fn taxability(rates: &[Rate], places: &[Place], id: &str, supply: Supply, on: &str) -> Result<Taxability, String> {
    taxability_with(rates, SUPPLY_RULES, places, id, supply, on)
}

/// [`taxability`] over an explicit rule table, so another jurisdiction's rules can be supplied
/// without touching the seeded ones.
pub fn taxability_with(
    rates: &[Rate],
    rules: &[SupplyRule],
    places: &[Place],
    id: &str,
    supply: Supply,
    on: &str,
) -> Result<Taxability, String> {
    let c = country(places, id)?;
    if c.system == Some(TaxSystem::ValueAdded) {
        return Err(format!(
            "{} operates VAT, and this module does not model it. Place-of-supply and the reverse charge decide who accounts for the tax on a cross-border service — treating a VAT rate as a sales tax rate produces an invoice that is wrong in a way nobody notices until an audit.",
            c.name
        ));
    }
    let chain = chain(places, id)?;
    let hit = chain.iter().find_map(|p| {
        rules
            .iter()
            .find(|r| r.place == p.id && r.supply == supply && r.from <= on && r.to.is_none_or(|t| on <= t))
    });
    let Some(rule) = hit else {
        return Ok(Taxability::Unknown {
            what_to_check: format!("whether {} is taxable in {id} on {on}", supply.label()),
            where_to_check: "that state's department of revenue — taxability of services and digital goods varies by state far more than the rate does, and no rule is recorded here for this one",
        });
    };
    if !rule.taxed {
        return Ok(Taxability::Exempt { reason: rule.reason, source: rule.source });
    }
    let (bps, found) = combined(rates, places, id, RateKind::SalesTax, on)?;
    let mut sources = dedup(&found.iter().map(|r| r.source).collect::<Vec<_>>());
    sources.push(rule.source);
    Ok(Taxability::Taxable { bps, sources })
}

/// The state (or province) a place sits in, if any. A country has none above it.
pub fn region(places: &[Place], id: &str) -> Result<Option<Place>, String> {
    Ok(chain(places, id)?.into_iter().find(|p| p.level == Level::Region))
}

/// Whether a SALE is taxed — which is not the same question as whether a supply is taxable here.
///
/// # Sales tax follows the CUSTOMER, not you
///
/// Georgia, like most states, sources a sale to its destination: the rate is the one where the
/// customer takes delivery, so a seller in Duluth shipping to another county charges THAT county's
/// rate rather than Gwinnett's. Using the seller's own rate is the intuitive mistake and it is wrong
/// on every invoice that leaves town.
///
/// # Across a state line this REFUSES, and the reason is nexus
///
/// Whether you must collect in another state at all depends on nexus — physical presence, or that
/// state's economic thresholds — and none of that is modelled here. Answering with a rate would
/// assert an obligation that may not exist, or miss one that does. So it refuses and says which
/// question to go answer.
///
/// # Exemption short-circuits all of it
///
/// If the supply is not taxable where it is sold from, there is nothing to source and no nexus
/// question to ask. That is the common case for a professional services practice, and it is why the
/// answer for one stays simple no matter who the customer is.
pub fn taxability_for_sale(
    rates: &[Rate],
    places: &[Place],
    seller: &str,
    buyer: Option<&str>,
    supply: Supply,
    on: &str,
) -> Result<Taxability, String> {
    taxability_for_sale_with(rates, SUPPLY_RULES, places, seller, buyer, supply, on)
}

/// [`taxability_for_sale`] over an explicit rule table.
pub fn taxability_for_sale_with(
    rates: &[Rate],
    rules: &[SupplyRule],
    places: &[Place],
    seller: &str,
    buyer: Option<&str>,
    supply: Supply,
    on: &str,
) -> Result<Taxability, String> {
    let at_seller = taxability_with(rates, rules, places, seller, supply, on)?;
    match at_seller {
        // Nothing to source. A service exempt in Georgia is exempt whoever buys it.
        Taxability::Exempt { .. } | Taxability::Unknown { .. } => Ok(at_seller),
        Taxability::Taxable { .. } => {
            let Some(buyer) = buyer else {
                return Ok(Taxability::Unknown {
                    what_to_check: format!(
                        "where the customer is — {} is taxable at {seller}, and the rate follows the customer rather than you",
                        supply.label()
                    ),
                    where_to_check: "record the buyer's place on the invoice; without it the rate cannot be sourced and a total cannot be computed",
                });
            };
            let (sr, br) = (region(places, seller)?, region(places, buyer)?);
            match (sr, br) {
                (Some(a), Some(b)) if a.id != b.id => Err(format!(
                    "this sale crosses from {} into {} and NEXUS is not modelled here. Whether you must collect in {} at all depends on physical presence or that state's economic thresholds — answering with a rate would assert an obligation that may not exist, or miss one that does. Check {}'s economic nexus threshold before charging or not charging.",
                    a.name, b.name, b.name, b.name
                )),
                _ => taxability_with(rates, rules, places, buyer, supply, on),
            }
        }
    }
}

/// Apply a basis-point rate to money. INTEGER throughout, rounding half away from zero.
///
/// `i128` because a large amount times ten thousand basis points overflows an `i64` sooner than
/// intuition suggests, and a silent wrap in a tax calculation is the worst possible failure.
pub fn apply_bps(m: Money, bps: i64) -> Money {
    let n = i128::from(m.minor) * i128::from(bps);
    let rounded = if n >= 0 { (n + 5_000) / 10_000 } else { (n - 5_000) / 10_000 };
    money(i64::try_from(rounded).unwrap_or(i64::MAX), m.currency)
}

/// The next date an obligation falls due, on or after `as_of`.
pub fn next_due(cadence: Cadence, as_of: &str) -> Option<String> {
    let Cadence::OnDates(dates) = cadence else { return None };
    let year: i32 = as_of.get(..4)?.parse().ok()?;
    let mut candidates: Vec<String> = Vec::new();
    for y in [year, year + 1] {
        for (m, d) in dates {
            candidates.push(format!("{y:04}-{m:02}-{d:02}"));
        }
    }
    candidates.sort();
    candidates.into_iter().find(|c| c.as_str() >= as_of)
}

/// Everything a place asks of you, nearest level LAST — federal first, then state, then the city,
/// which is the order somebody actually works through them.
pub fn obligations_for(obligations: &[Obligation], places: &[Place], id: &str) -> Result<Vec<Obligation>, String> {
    let mut c = chain(places, id)?;
    c.reverse();
    Ok(c.iter().flat_map(|p| obligations.iter().filter(|o| o.place == p.id).cloned()).collect())
}

/// What a place can actually ANSWER, following the chain — not what happens to be declared at its
/// own id.
///
/// Duluth declares no rate of its own and inherits every one that applies to it, so labelling it by
/// what is attached to that id alone reported "name only" for the one place the whole seed was built
/// for. The question a reader is asking is whether asking HERE gets an answer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Coverage {
    pub sales_tax: bool,
    pub supply_rules: bool,
    pub obligations: bool,
}

impl Coverage {
    pub fn label(self) -> &'static str {
        match (self.sales_tax, self.supply_rules) {
            (true, true) => "rates + rules",
            (true, false) => "rates only",
            (false, true) => "rules only",
            (false, false) if self.obligations => "duties only",
            (false, false) => "name only",
        }
    }
}

pub fn coverage(rates: &[Rate], rules: &[SupplyRule], obligations: &[Obligation], places: &[Place], id: &str, on: &str) -> Coverage {
    let chain = chain(places, id).unwrap_or_default();
    Coverage {
        sales_tax: combined(rates, places, id, RateKind::SalesTax, on).is_ok(),
        supply_rules: chain
            .iter()
            .any(|p| rules.iter().any(|r| r.place == p.id && r.from <= on && r.to.is_none_or(|t| on <= t))),
        obligations: chain.iter().any(|p| obligations.iter().any(|o| o.place == p.id)),
    }
}

/// Every figure in the table with the source it came from — the one pass that turns this from a
/// plausible list into a checked one. NOTHING here has been verified by a human.
pub fn sources(rates: &[Rate], obligations: &[Obligation]) -> Vec<(&'static str, &'static str)> {
    let mut out: Vec<(&'static str, &'static str)> = Vec::new();
    for r in rates {
        out.push((r.place, r.source));
    }
    for o in obligations {
        out.push((o.place, o.source));
    }
    let mut seen: Vec<(&'static str, &'static str)> = Vec::new();
    for x in out {
        if !seen.contains(&x) {
            seen.push(x);
        }
    }
    seen
}

