            assert_eq!(Supply::parse(sup.key()), Some(*sup), "{} did not round trip", sup.key());
        }
        assert_eq!(Supply::ALL.len(), 4, "a new supply kind needs a key here or it cannot be stored");
        assert_eq!(Supply::parse("services"), None, "a near miss must not resolve — a typo would decide taxability");
        assert_eq!(Supply::parse(""), None);
    }

    #[test]
    fn a_region_resolves_through_the_chain_and_a_country_has_none() {
        assert_eq!(region(PLACES, "us/ga/gwinnett/duluth").expect("resolvable").map(|p| p.id), Some("us/ga"));
        assert_eq!(region(PLACES, "us/ga").expect("resolvable").map(|p| p.id), Some("us/ga"));
        assert_eq!(region(PLACES, "us").expect("resolvable").map(|p| p.id), None, "a country sits above every region");
    }

    #[test]
    fn applying_a_rate_stays_in_integers_and_rounds_half_away_from_zero() {
        assert_eq!(apply_bps(usd(10_000), 600).minor, 600, "6% of 100.00 is 6.00");
        // 0.005 exactly — rounds up, not to even, because that is what a tax table does.
        assert_eq!(apply_bps(usd(25), 200).minor, 1, "2% of 0.25 is 0.005");
        assert_eq!(apply_bps(usd(-25), 200).minor, -1, "and the same magnitude the other way");
        assert_eq!(apply_bps(usd(0), 600).minor, 0);
        // A large amount does not wrap: 10 million dollars at 6%.
        assert_eq!(apply_bps(usd(1_000_000_000), 600).minor, 60_000_000);
    }

    #[test]
    fn every_seeded_rate_cites_a_source() {
        // A rate with no source is a rumour, and this table is the input to a tax return.
        assert!(RATES.len() >= 4, "the scan found only {} rates — it has stopped seeing them", RATES.len());
        for r in RATES {
            assert!(!r.source.trim().is_empty(), "{} {} has no source", r.place, r.kind.label());
            assert!(r.from.len() == 10, "{} {} has no usable effective date", r.place, r.kind.label());
        }
        assert!(SUPPLY_RULES.len() >= 4, "the scan found only {} supply rules", SUPPLY_RULES.len());
        for r in SUPPLY_RULES {
            assert!(!r.source.trim().is_empty(), "{} {:?} has no source", r.place, r.supply);
            assert!(!r.reason.trim().is_empty(), "{} {:?} gives no reason — an exemption you cannot explain is one you cannot defend", r.place, r.supply);
            assert!(PLACES.iter().any(|p| p.id == r.place), "`{}` is ruled on but is not a seeded place", r.place);
        }
        assert!(OBLIGATIONS.len() >= 7, "the scan found only {} obligations", OBLIGATIONS.len());
        for o in OBLIGATIONS {
            assert!(!o.source.trim().is_empty(), "{} has no source", o.name);
            assert!(!o.authority.trim().is_empty(), "{} names no authority — a requirement you cannot act on", o.name);
            assert!(!o.required_when.trim().is_empty(), "{} does not say when it applies, so it reads as always", o.name);
        }
        // And every place a rate or obligation points at must actually exist.
        for (place, _) in sources(RATES, OBLIGATIONS) {
            assert!(PLACES.iter().any(|p| p.id == place), "`{place}` is cited but is not a seeded place");
        }
    }

    #[test]
    fn the_other_states_exist_as_names_and_assert_no_rate_or_rule() {
        // The whole point of seeding them: they must add REACH without adding false precision.
        assert!(PLACES.iter().filter(|p| p.level == Level::Region).count() >= 50, "the states are the reach");
        for p in PLACES.iter().filter(|p| p.level == Level::Region && p.id != "us/ga") {
            assert!(!RATES.iter().any(|r| r.place == p.id), "{} asserts a rate nobody checked", p.id);
            assert!(!SUPPLY_RULES.iter().any(|r| r.place == p.id), "{} asserts a taxability rule nobody checked", p.id);
        }
        // So each answers NOT KNOWN rather than a number, and says so.
        let t = taxability(RATES, PLACES, "us/tx", Supply::ProfessionalService, "2026-09-04").expect("resolvable");
        assert!(matches!(t, Taxability::Unknown { .. }), "{t:?}");
        assert!(combined(RATES, PLACES, "us/tx", RateKind::SalesTax, "2026-09-04").is_err());
        // The federal obligations still reach them, which is the value of existing at all.
        let obs = obligations_for(OBLIGATIONS, PLACES, "us/tx").expect("resolvable");
        assert!(obs.iter().any(|o| o.name == "Estimated tax"), "federal duties do not stop at a state line");
        assert!(obs.iter().all(|o| o.place == "us"), "nothing state-specific may be claimed for Texas: {:?}", obs.iter().map(|o| o.place).collect::<Vec<_>>());
    }

    #[test]
    fn coverage_follows_the_chain_so_duluth_is_not_reported_as_unknown() {
        let cov = |id: &str| coverage(RATES, SUPPLY_RULES, OBLIGATIONS, PLACES, id, "2026-09-04");
        // THE MISREADING THIS FIXES. Duluth declares no rate of its own and inherits every one that
        // applies; labelling it by its own id alone called the seed's whole purpose "name only".
        assert_eq!(cov("us/ga/gwinnett/duluth").label(), "rates + rules");
        assert_eq!(cov("us/ga").label(), "rates + rules");
        // A state with nothing recorded says so, and still carries the federal duties.
        let tx = cov("us/tx");
        assert_eq!(tx.label(), "duties only");
        assert!(!tx.sales_tax && !tx.supply_rules && tx.obligations);
        // The country itself has federal obligations and a self-employment rate, but no sales tax.
        assert!(!cov("us").sales_tax, "there is no federal sales tax");
    }

    #[test]
    fn a_cross_state_sale_now_refuses_for_the_right_reason() {
        // BEFORE the states were seeded this failed as "not a place this knows", which is a true
        // statement that answers the wrong question. Now it names nexus.
        let err = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::DigitalProduct, "2026-09-04").unwrap_err();
        assert!(err.contains("NEXUS is not modelled"), "{err}");
        assert!(err.contains("California"), "{err}");
        // And a service is STILL exempt across that line, because exemption short-circuits sourcing.
        let svc = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::ProfessionalService, "2026-09-04").expect("exempt regardless");
        assert!(matches!(svc, Taxability::Exempt { .. }), "{svc:?}");
    }

    #[test]
    fn every_place_reaches_a_country_that_declares_a_currency_and_a_system() {
        for p in PLACES {
            let c = country(PLACES, p.id).unwrap_or_else(|e| panic!("{}: {e}", p.id));
            assert!(c.currency.is_some(), "{} reaches {} which declares no currency", p.id, c.id);
            assert!(c.system.is_some(), "{} reaches {} which declares no tax system", p.id, c.id);
        }
        assert_eq!(country(PLACES, "us/ga/gwinnett/duluth").expect("seeded").id, "us");
    }
